import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import "./Menu.css";
import { Dropdown, OverlayTrigger, Popover } from "react-bootstrap";
import { Cart3, SortDown, SortUp } from "react-bootstrap-icons";

export default function Menu({
  countCartItems,
  categories,
  renderCart,
  onLinkClick,
  onSortClick,
  sort,
}) {
  const [activeCategory, setActiveCategory] = useState("All");

  const sortOptions = [
    { key: "title", label: "By Name" },
    { key: "price", label: "By Price" },
    { key: "category", label: "By Category" },
  ];

  const handleCategoryClick = (id) => {
    setActiveCategory(id);
    onLinkClick(id);
  };

  const handleSortClick = (key) => {
    const active = sort && sort.name === key;
    onSortClick({
      name: key,
      order: active && sort.order === "asc" ? "desc" : "asc",
    });
  };

  const getSortLabel = () => {
    if (!sort || sort.name === "id") return "Sort";
    const option = sortOptions.find((o) => o.key === sort.name);
    return option ? option.label : "Sort";
  };

  const cartPopover = (
    <Popover className="gb-cart-popover">
      <Popover.Header className="gb-cart-popover-header">
        Your Cart
      </Popover.Header>
      <Popover.Body className="gb-cart-popover-body">
        {renderCart()}
      </Popover.Body>
    </Popover>
  );

  return (
    <header className="gb-header">
      <div className="gb-header-inner">
        {/* Brand */}
        <div className="gb-brand">
          <span className="gb-brand-icon">🌿</span>
          <span className="gb-brand-name">
            Grocery<span className="gb-brand-accent">Basket</span>
          </span>
        </div>

        {/* Category Pills */}
        <nav className="gb-categories" aria-label="Product categories">
          {categories.map((cat) => (
            <button
              key={cat.id}
              className={`gb-cat-pill${activeCategory === cat.id ? " active" : ""}`}
              onClick={() => handleCategoryClick(cat.id)}
            >
              {cat.title}
            </button>
          ))}
        </nav>

        {/* Right Actions */}
        <div className="gb-actions">
          {/* Sort */}
          <Dropdown className="gb-sort-dropdown">
            <Dropdown.Toggle id="gb-sort-toggle">
              {getSortLabel()}
              {sort && sort.name !== "id" && (
                sort.order === "asc"
                  ? <SortUp size={13} />
                  : <SortDown size={13} />
              )}
            </Dropdown.Toggle>
            <Dropdown.Menu className="gb-sort-menu">
              {sortOptions.map(({ key, label }) => (
                <Dropdown.Item
                  key={key}
                  className={`gb-sort-item${sort && sort.name === key ? " active" : ""}`}
                  onClick={() => handleSortClick(key)}
                >
                  <span>{label}</span>
                  {sort && sort.name === key && (
                    sort.order === "asc"
                      ? <SortUp size={12} />
                      : <SortDown size={12} />
                  )}
                </Dropdown.Item>
              ))}
              <Dropdown.Divider />
              <Dropdown.Item
                className="gb-sort-item"
                onClick={() => onSortClick({ name: "id", order: "asc" })}
              >
                Clear Sort
              </Dropdown.Item>
            </Dropdown.Menu>
          </Dropdown>

          {/* Cart */}
          <OverlayTrigger
            trigger="click"
            placement="bottom-end"
            overlay={cartPopover}
            rootClose
          >
            <button className="gb-cart-btn">
              <Cart3 size={17} />
              <span className="gb-cart-btn-label">Cart</span>
              {countCartItems > 0 && (
                <span className="gb-cart-badge">{countCartItems}</span>
              )}
            </button>
          </OverlayTrigger>
        </div>
      </div>
    </header>
  );
}
