import React from "react";

export default function Cartlist({ onAdd, cartItems, onRemove }) {
  const total = cartItems.reduce((a, c) => a + c.price * c.qty, 0);

  if (cartItems.length === 0) {
    return (
      <div className="cart-empty">
        <span className="cart-empty-emoji">🛒</span>
        <p className="cart-empty-text">Your cart is empty</p>
      </div>
    );
  }

  return (
    <>
      <ul className="cart-items-list">
        {cartItems.map((item) => (
          <li key={item.id} className="cart-item-row">
            <div className="cart-item-info">
              <p className="cart-item-name">{item.title}</p>
              <p className="cart-item-unit">₹{item.price} each</p>
            </div>
            <div className="qty-controls">
              <button className="qty-btn minus" onClick={() => onRemove(item)}>
                −
              </button>
              <span className="qty-display">{item.qty}</span>
              <button className="qty-btn plus" onClick={() => onAdd(item)}>
                +
              </button>
            </div>
            <span className="cart-item-subtotal">
              ₹{(item.qty * item.price).toFixed(0)}
            </span>
          </li>
        ))}
      </ul>
      <div className="cart-footer">
        <div className="cart-total-row">
          <span className="cart-total-label">Total</span>
          <span className="cart-total-amount">₹{total.toFixed(2)}</span>
        </div>
        <button className="checkout-btn">Checkout →</button>
      </div>
    </>
  );
}
